INSERT INTO `demon_achievement` VALUES (1,'first_step','初入魔道','启','道途','煞气累计 50','魔气初凝，道途自此而始。','exp',50,'引煞童子','初入',1,1,'2026-11-06 09:20:20'),(2,'realm_3','魔尉之阶','尉','道途','修至魔尉境','过魔卒而掌一队魔兵，方算登堂。','realm_index',3,'魔门都尉','登堂',2,1,'2026-11-06 09:20:20'),(3,'realm_7','魔祖临世','祖','道途','修至魔祖境','一域之尊，诸魔俯首。','realm_index',7,'一方魔祖','大成',3,1,'2026-11-06 09:20:20'),(4,'realm_9','无上魔圣','圣','道途','修至无上境','十境之巅，魔道尽头。','realm_index',9,'无上魔圣','圆满',4,1,'2026-11-06 09:20:20'),(5,'layer_18','二重九转','转','修行','累计境界重数 18','两境九重俱满，根基始固。','total_layer',18,'九转修士','登堂',5,1,'2026-11-06 09:20:20'),(6,'layer_45','五境九重','重','修行','累计境界重数 45','五境皆至九重圆满。','total_layer',45,'九重圆满','大成',6,1,'2026-11-06 09:20:20'),(7,'sign_7','七日不辍','香','日课','连续焚香 7 日','香火不断，心志不摇。','sign_streak',7,'长明香主','初入',7,1,'2026-11-06 09:20:20'),(8,'sign_30','月月焚香','恒','日课','累计焚香 30 日','一月之期，日日不废。','sign_total',30,'焚香行者','登堂',8,1,'2026-11-06 09:20:20'),(9,'quiz_10','十论皆通','辩','论道','答对 10 道不同论题','论道台上十问不倒。','quiz_correct',10,'辩才无碍','登堂',9,1,'2026-11-06 09:20:20'),(10,'quiz_20','论道宗师','宗','论道','答对 20 道不同论题','题库尽通，魔门无出其右。','quiz_correct',20,'论道宗师','圆满',10,1,'2026-11-06 09:20:20'),(11,'read_20','博览群魔','卷','图鉴','研读 20 篇不同典籍','藏经殿中已有你的足迹。','read_distinct',20,'博览魔典','初入',11,1,'2026-11-06 09:20:20'),(12,'read_50','典册尽览','印','图鉴','研读 50 篇不同典籍','魔枢典册尽入胸中。','read_distinct',50,'藏经执印','大成',12,1,'2026-11-06 09:20:20'),(13,'art_3','兼修三门','法','修行','习得 3 部功法','不再倚仗一门之技。','art_count',3,'兼修三门','登堂',13,1,'2026-11-06 09:20:20'),(14,'art_10','万法归一','万','修行','习得 10 部功法','诸法并蓄，终归一道。','art_count',10,'万法归一','圆满',14,1,'2026-11-06 09:20:20'),(15,'art_supreme','无上道果','果','修行','任一功法修至无上','死战悟道之后，战力跨阶。','art_stage',6,'道果执掌','圆满',15,1,'2026-11-06 09:20:20'),(16,'spar_10','演武翘楚','战','修行','切磋胜 10 场','演武场上少有敌手。','spar_win',10,'演武翘楚','登堂',16,1,'2026-11-06 09:20:20'),(17,'den_15','洞府初成','窟','洞府','洞府三设施等级合计 15','聚煞阵与矿脉皆已成形。','den_sum',15,'洞天初辟','登堂',17,1,'2026-11-06 09:20:20'),(18,'den_30','三阵圆满','府','洞府','洞府三设施等级合计 30','三阵尽满，坐拥一窟。','den_sum',30,'魔窟之主','圆满',18,1,'2026-11-06 09:20:20'),(19,'coin_5000','富甲一方','晶','财富','累计获得 5000 魔晶','富甲榜上留名。','coin_earned',5000,'富甲一方','大成',19,1,'2026-11-06 09:20:20'),(20,'jade_100','血玉盈囊','玉','财富','累计获得 100 血玉','血玉积至盈囊。','jade_earned',100,'血玉盈囊','大成',20,1,'2026-11-06 09:20:20'),(21,'friend_5','五方魔友','友','交游','结交 5 位魔友','传音之谊，遍结魔域。','friend_count',5,'呼朋唤魔','登堂',21,1,'2026-11-06 09:20:20'),(22,'trade_3','鬼市常客','市','交游','鬼市成交卖出 3 笔','鬼市之中信誉已立。','trade_sold',3,'鬼市常客','登堂',22,1,'2026-11-06 09:20:20'),(23,'reincarnate_1','一转轮回','轮','终极','转世重修 1 次','舍却一身修为，换得道基更厚。','reincarnate',1,'轮回者','圆满',23,1,'2026-11-06 09:20:20'),(24,'reincarnate_10','十世魔主','世','终极','转世重修 10 次','十世圆满，倍率封顶。','reincarnate',10,'十世魔主','无上',24,1,'2026-11-06 09:20:20'),(25,'daily_all','日课无缺','课','日课','一日之内七项日课全满','焚香、参悟、论道、切磋、研读、秘境、洞府收取，一项不落。','daily_all',7,'日课无缺','小成',25,1,'2026-11-06 09:20:20');
