INSERT INTO `demon_announcement` VALUES (1,'魔门开宗大典','三月初三，魔主将于血煞峰开宗大典，诸修皆可赴会论道。','喜讯','2026-10-26 09:02:42'),(2,'煞气异动警示','北境万骨荒原煞气骤盛，魔卒以下慎入，免遭反噬。','警示','2026-10-26 09:02:42'),(3,'新典入库','《星陨录》《冥河志异》等上古残卷已入魔典秘录，诸修可往查阅。','通告','2026-10-26 09:02:42'),(4,'论道延期','原定本月的「群魔共治」论道因魔渊异动延期，另择吉日。','通告','2026-10-26 09:02:42'),(5,'秘辛·禁忌之扉','卷末禁忌之扉似有松动，擅窥者多遭反噬，切记慎之。','秘辛','2026-10-26 09:02:42');
