--
-- Table structure for table `demon_art`
--

DROP TABLE IF EXISTS `demon_art`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `demon_art` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '功法名',
  `category` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '类别：攻伐/护体/幻术/炼魂/御兽',
  `grade` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '品阶：黄/玄/地/天/仙',
  `layer` int NOT NULL DEFAULT '1' COMMENT '功法重数（黄1-4 玄1-6 地1-7 天1-10 仙1-10）',
  `series` varchar(60) DEFAULT NULL COMMENT '功法系列（同系列须按重递进购买）',
  `price_coin` int NOT NULL DEFAULT '0' COMMENT '售价·魔晶（0 且 price_jade=0 表示免费）',
  `price_jade` int NOT NULL DEFAULT '0' COMMENT '售价·血玉（>0 时优先以血玉计价）',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1=在售 0=下架',
  `bonus_atk` int NOT NULL DEFAULT '0' COMMENT '攻伐加成',
  `bonus_def` int NOT NULL DEFAULT '0' COMMENT '护体加成',
  `bonus_hp` int NOT NULL DEFAULT '0' COMMENT '气血加成',
  `bonus_insight` int NOT NULL DEFAULT '0' COMMENT '悟性加成',
  `bonus_agility` int NOT NULL DEFAULT '0' COMMENT '身法加成',
  `realm_req` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '所需境界',
  `summary` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '简介',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '正文',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '配图相对路径',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_art_name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='功法阁';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `demon_art`
--

