INSERT INTO `demon_art` VALUES (1,'太初魔经','炼魂','仙',1,'太初魔经',0,600,1,108,81,600,40,60,'血煞','太初之魔留下的第一篇经文；读之者，皆入魔道。','太初之魔留下的第一篇经文；读之者，皆入魔道。\n\n【功法品阶】仙阶\n【修行要旨】此法直指神魂。修炼时以煞气温养魂魄，神念愈纯；重数既深，可窥人心、可夺人魄。\n【进度之说】入门 → 小成 → 大成 → 圆满 → 入道 → 无上，六重各成气象。残篇只得其形，最高修至大成，威能折损四成有余；完整卷方可续修圆满、入道、无上。每部功法每日可修三课，每课耗煞气十点。','2026-11-05 17:41:09','/images/art/art-1.jpg'),(2,'混元血煞图','护体','仙',2,'混元血煞图',0,600,1,192,243,1440,60,108,'血煞','以血煞绘就的混元图，护持道基不坠；图成，身即道。','以血煞绘就的混元图，护持道基不坠；图成，身即道。\n\n【功法品阶】仙阶\n【修行要旨】此法以身为城。修炼时纳煞入骨，层层叠甲；重数越深，护体越厚，纵是群魔围攻亦难破。\n【进度之说】入门 → 小成 → 大成 → 圆满 → 入道 → 无上，六重各成气象。残篇只得其形，最高修至大成，威能折损四成有余；完整卷方可续修圆满、入道、无上。每部功法每日可修三课，每课耗煞气十点。','2026-11-05 17:41:09','/images/art/art-2.jpg'),(3,'血煞戮天诀','攻伐','仙',3,'血煞戮天诀',0,600,1,414,230,1710,90,180,'血煞','以血煞之气凝刃，一念可斩千军；刃出，天亦为之变色。','以血煞之气凝刃，一念可斩千军；刃出，天亦为之变色。\n\n【功法品阶】仙阶\n【修行要旨】此法以杀证道。修炼时以煞气淬炼锋锐，每进一重，出手便重一分；至大成时，同阶护体亦可一击而破。\n【进度之说】入门 → 小成 → 大成 → 圆满 → 入道 → 无上，六重各成气象。残篇只得其形，最高修至大成，威能折损四成有余；完整卷方可续修圆满、入道、无上。每部功法每日可修三课，每课耗煞气十点。','2026-10-26 09:02:42','/images/art/art-3.jpg'),(4,'御兽血契','御兽','天',1,'御兽血契',0,150,1,70,52,438,17,37,'魔尉','与异兽立血契，共赴杀伐；契成之后，生死同途。','与异兽立血契，共赴杀伐；契成之后，生死同途。\n\n【功法品阶】天阶\n【修行要旨】此法以契为纲。修炼时以血煞立契，驱使异类；契愈深，所驱之物愈强。\n【进度之说】入门 → 小成 → 大成 → 圆满 → 入道 → 无上，六重各成气象。残篇只得其形，最高修至大成，威能折损四成有余；完整卷方可续修圆满、入道、无上。每部功法每日可修三课，每课耗煞气十点。','2026-10-26 09:02:42','/images/art/art-4.jpg'),(5,'天魔解体大法','炼魂','天',1,'天魔解体大法',0,150,1,63,47,350,24,35,'魔尉','解体重凝，以魂换力；魂越散，力越狂。','解体重凝，以魂换力；魂越散，力越狂。\n\n【功法品阶】天阶\n【修行要旨】此法直指神魂。修炼时以煞气温养魂魄，神念愈纯；重数既深，可窥人心、可夺人魄。\n【进度之说】入门 → 小成 → 大成 → 圆满 → 入道 → 无上，六重各成气象。残篇只得其形，最高修至大成，威能折损四成有余；完整卷方可续修圆满、入道、无上。每部功法每日可修三课，每课耗煞气十点。','2026-11-05 17:41:09','/images/art/art-5.jpg'),(6,'焚天业火','攻伐','天',4,'焚天业火',0,150,1,322,178,1330,70,140,'魔将','引业火焚身，敌我皆烬；业不尽，火不熄。','引业火焚身，敌我皆烬；业不尽，火不熄。\n\n【功法品阶】天阶\n【修行要旨】此法以杀证道。修炼时以煞气淬炼锋锐，每进一重，出手便重一分；至大成时，同阶护体亦可一击而破。\n【进度之说】入门 → 小成 → 大成 → 圆满 → 入道 → 无上，六重各成气象。残篇只得其形，最高修至大成，威能折损四成有余；完整卷方可续修圆满、入道、无上。每部功法每日可修三课，每课耗煞气十点。','2026-10-26 09:02:42','/images/art/art-6.jpg'),(7,'血河大阵','护体','天',4,'血河大阵',0,150,1,224,284,1680,70,126,'魔将','布血河为阵，万法不侵；河不枯，阵不破。','布血河为阵，万法不侵；河不枯，阵不破。\n\n【功法品阶】天阶\n【修行要旨】此法以身为城。修炼时纳煞入骨，层层叠甲；重数越深，护体越厚，纵是群魔围攻亦难破。\n【进度之说】入门 → 小成 → 大成 → 圆满 → 入道 → 无上，六重各成气象。残篇只得其形，最高修至大成，威能折损四成有余；完整卷方可续修圆满、入道、无上。每部功法每日可修三课，每课耗煞气十点。','2026-10-26 09:02:42','/images/art/art-7.jpg'),(8,'天煞魔瞳','幻术','天',6,'天煞魔瞳',0,150,1,357,268,1890,121,284,'血煞','魔瞳开阖，摄魂夺魄；瞳光所至，心志尽摧。','魔瞳开阖，摄魂夺魄；瞳光所至，心志尽摧。\n\n【功法品阶】天阶\n【修行要旨】此法以心为战场。修炼时以煞气养瞳炼神，一重深似一重；及至大成，可令人自陷其境而不自知。\n【进度之说】入门 → 小成 → 大成 → 圆满 → 入道 → 无上，六重各成气象。残篇只得其形，最高修至大成，威能折损四成有余；完整卷方可续修圆满、入道、无上。每部功法每日可修三课，每课耗煞气十点。','2026-11-05 17:41:09','/images/art/art-8.jpg'),(9,'地煞裂山掌','攻伐','地',1,'地煞裂山掌',0,40,1,57,32,238,12,25,'魔卒','一掌裂山，山岳崩摧。地阶开门第一式，重在势。','一掌裂山，山岳崩摧。地阶开门第一式，重在势。\n\n【功法品阶】地阶\n【修行要旨】此法以杀证道。修炼时以煞气淬炼锋锐，每进一重，出手便重一分；至大成时，同阶护体亦可一击而破。\n【进度之说】入门 → 小成 → 大成 → 圆满 → 入道 → 无上，六重各成气象。残篇只得其形，最高修至大成，威能折损四成有余；完整卷方可续修圆满、入道、无上。每部功法每日可修三课，每课耗煞气十点。','2026-11-05 17:41:09','/images/art/art-9.jpg'),(10,'幽壤护心甲','护体','地',1,'幽壤护心甲',0,40,1,40,51,300,12,22,'魔卒','取九幽之壤铸甲，护心不破，万煞难侵。','取九幽之壤铸甲，护心不破，万煞难侵。\n\n【功法品阶】地阶\n【修行要旨】此法以身为城。修炼时纳煞入骨，层层叠甲；重数越深，护体越厚，纵是群魔围攻亦难破。\n【进度之说】入门 → 小成 → 大成 → 圆满 → 入道 → 无上，六重各成气象。残篇只得其形，最高修至大成，威能折损四成有余；完整卷方可续修圆满、入道、无上。每部功法每日可修三课，每课耗煞气十点。','2026-11-05 17:41:09','/images/art/art-10.jpg'),(11,'玄阴养魂诀','炼魂','地',2,'玄阴养魂诀',0,40,1,90,68,500,34,50,'魔卒','温养神魂，稳固道基。修行愈深，心魔愈难侵。','温养神魂，稳固道基。修行愈深，心魔愈难侵。\n\n【功法品阶】地阶\n【修行要旨】此法直指神魂。修炼时以煞气温养魂魄，神念愈纯；重数既深，可窥人心、可夺人魄。\n【进度之说】入门 → 小成 → 大成 → 圆满 → 入道 → 无上，六重各成气象。残篇只得其形，最高修至大成，威能折损四成有余；完整卷方可续修圆满、入道、无上。每部功法每日可修三课，每课耗煞气十点。','2026-10-26 09:02:42','/images/art/art-11.jpg'),(12,'地渊尸潮','御兽','地',2,'地渊尸潮',0,40,1,100,75,625,24,52,'魔卒','开地渊之门，尸潮涌出；所过之处，唯余白骨。','开地渊之门，尸潮涌出；所过之处，唯余白骨。\n\n【功法品阶】地阶\n【修行要旨】此法以契为纲。修炼时以血煞立契，驱使异类；契愈深，所驱之物愈强。\n【进度之说】入门 → 小成 → 大成 → 圆满 → 入道 → 无上，六重各成气象。残篇只得其形，最高修至大成，威能折损四成有余；完整卷方可续修圆满、入道、无上。每部功法每日可修三课，每课耗煞气十点。','2026-11-05 17:41:09','/images/art/art-12.jpg'),(13,'玄冰魔镜','幻术','地',4,'玄冰魔镜',0,40,1,170,128,900,57,135,'魔尉','魔镜映心，困敌于镜中；镜碎之时，神魂俱裂。','魔镜映心，困敌于镜中；镜碎之时，神魂俱裂。\n\n【功法品阶】地阶\n【修行要旨】此法以心为战场。修炼时以煞气养瞳炼神，一重深似一重；及至大成，可令人自陷其境而不自知。\n【进度之说】