INSERT INTO `demon_codex` VALUES (1,'太古魔典','卷一·开辟','记述魔域开天辟地之秘，言魔气自混沌中来。','2026-10-26 09:02:42','/images/codex/codex-1.jpg'),(2,'噬魂真解','卷三·炼魂','详述炼魂锁魄之法门与禁忌，阅前须立护心咒。','2026-10-26 09:02:42','/images/codex/codex-2.jpg'),(3,'血煞图谱','卷七·攻伐','血煞一脉功法源流与图谱，脉络清晰。','2026-10-26 09:02:42','/images/codex/codex-3.jpg'),(4,'幽冥往生录','卷九·往生','幽冥轮回之说，真假难辨，录以备参。','2026-10-26 09:02:42','/images/codex/codex-4.jpg'),(5,'禁忌之扉','卷末·禁忌','封印于魔域最深处之禁忌知识，擅窥者或遭反噬。','2026-10-26 09:02:42','/images/codex/codex-5.jpg'),(6,'万兽图录','卷四·御兽','记魔渊异兽形貌习性，御兽者必参。','2026-10-26 09:02:42','/images/codex/codex-6.jpg'),(7,'寒煞秘要','卷六·攻伐','寒煞一脉修炼次第与破法，循序渐进。','2026-10-26 09:02:42','/images/codex/codex-7.jpg'),(8,'冥河志异','卷十·异闻','冥河两岸奇闻怪谈，虚实参半，录以警世。','2026-10-26 09:02:42','/images/codex/codex-8.jpg'),(9,'星陨录','卷十一·天象','残星坠落之兆与魔劫关联考，关乎魔域气运。','2026-10-26 09:02:42','/images/codex/codex-9.jpg');
/*!40000 ALTER TABLE `demon_codex` ENABLE KEYS */;
UNLOCK TABLES;

--
