INSERT INTO `demon_debate` VALUES (1,'魔非魔，道非道','魔祖','顺逆由心，何须外求；魔与道，不过一念之转。','魔由心生，道由心灭','魔道本一体，一念之转','魔即魔，道即道，永不相容','B','万法唯心所现，魔与道不过执念两分；顺逆由心，转念即是转境。','2026-10-26 09:02:42'),(2,'血契之辩','血煞尊者','以血为契，究竟是束缚，还是自由？','血契是束缚，斩之即自由','血契是枷锁，亦是修行的磨刀石','自由与束缚皆在己心，血契只是镜','C','以血为契，缚的是身，试的是心；视其为磨刀石还是牢笼，只在一念。','2026-10-26 09:02:42'),(3,'杀伐与慈悲','幽冥夫人','魔道修行，可存一线慈悲否？','魔道无情，慈悲是弱者的伪装','杀伐为主，慈悲为佐，方为长久','慈悲即杀伐，杀伐即慈悲','B','一味杀伐则众叛亲离，一味慈悲则道基不固；一线慈悲存于杀伐之中，方是中道。','2026-10-26 09:02:42'),(4,'长生孰真','虚妄上人','长生不过执念，何为真我？','长生是真，寿与天齐即是解脱','长生是妄，舍寿方见真我','长生无所谓真假，体验本身即是意义','B','执念于不死者，恰被不死所缚；放下长生之执，方能在有限中见真我。','2026-10-26 09:02:42'),(5,'群魔共治','噬魂大王','魔域当立规制，还是任凭弱肉强食？','弱肉强食即天理，规制是伪善','当立规制，无序则魔域自毁','规制由强者制定，强者更迭则规制更迭','B','群魔共治需规制为骨：无规制的魔域终将在内耗中崩塌，强弱轮转亦需秩序承载。','2026-10-26 09:02:42'),(6,'寂灭与轮回','寂灭尊者','魔修可证寂灭，抑或只入轮回？','寂灭为归，轮回为苦','轮回为归，寂灭为断','寂灭与轮回皆途，道心所向即是归处','C','执着寂灭是断，执着轮回是迷；魔修之路不在归处，而在道心所向。','2026-10-26 09:02:42'),(7,'力量之价','血河老祖','无敌之力，是否必以本心为祭？','力量即一切，本心可弃','本心为本，力量为用，不可倒置','力量与本心并行不悖，无需取舍','B','以本心祭力量者，终成力量的傀儡；力为用、心为本，用不伤本方是正途。','2026-10-26 09:02:42'),(8,'魔域之疆','幽冥夫人','魔域当有边界，还是无垠扩张？','魔域当有边界，守成方安','魔域当无垠扩张，停滞即死亡','疆界在心不在土，心之所在即魔域','C','有形之疆终有尽时，无形之疆随道心而长；守成与扩张皆是外相，心疆无边方是真无垠。','2026-10-26 09:02:42'),(9,'煞气何来','引煞长老','魔道修行以煞气为基，世人皆言煞气乃杀伐之气，那么它究竟从何而生？','众生执念所积，观魔域万象而自聚','杀戮取命，唯杀生方得煞气','天授之，生而有之','A','煞气非杀伐所生，乃众生执念汇聚。故参悟魔域、论道辨析皆可纳煞，不必染血。','2026-11-02 09:49:29'),(10,'境界压制之虚实','萧寒山','高境者临敌，其压制之力究竟源于境界本身，还是源于积累的煞气？','纯粹是位阶之差，与煞气无关','只看煞气多寡，位阶虚名而已','位阶定根本，煞气填血肉，二者相合方成战力','C','战力者，位阶乘千再加煞气。位阶是骨架，煞气是血肉。境界差两重以上，低者战力折损三成。','2026-11-02 09:49:29'),(11,'四系魔种之辨','虚妄上人','血煞、幽冥、噬魂、虚妄四系，择其一而后终身为限，此择是否要紧？','各系天赋不同，择种即定其修行偏向','只是名号，全无实际差别','可随时改易，随心而变','A','四系各有所长：血煞善战、幽冥纳煞、噬魂掠夺、虚妄顿悟。择种，便是择一条路数的开头。','2026-11-02 09:49:29'),(12,'心魔何以为魔','寂灭尊者','修行者走火入魔，究竟是被外力侵蚀，还是自心失守？','外魔入侵，防之当在外','心念一乱，自心即魔','修行过急，必然走火','B','魔自心生。外境只是引子，真正动摇道心的，从来都是自己的执念。','2026-11-02 09:49:29'),(13,'切磋是否夺人道行','血河老祖','同门切磋，胜负既定便各有增损。那么切磋算不算夺人道行？','不算，煞气往来如活水，流转方能精进','算，故当禁止','只在胜负悬殊时才算','A','煞气不是死物。切磋取其流转，败者失、胜者得，如磨刀石相互砥砺，并非掠夺。','2026-11-02 09:49:29'),(14,'境界与功法','魔祖','已至高位者，是否还需回头修习低阶功法？','不必，境界已足，功法皆小道','全看功法之名是否够响亮','境界为体，功法为用，体用不可偏废','C','境界是修为的容量，功法是运用的法门。空有境界而无功法，如持巨鼎而不知如何举。','2026-11-02 09:49:29'),(15,'历练之所求','燕孤鸿','入历练之地，究竟为取宝、为杀敌、还是为阅世？','为阅世，见天地而后知自身之限','为杀，杀得多者功高','为宝，有所得方不虚此行','A','历练之本，在于见未曾见之物、遇未曾遇之险。宝物可失，所见长存。','2026-11-02 09:49:29'),(16,'魔籍为何留名','典册执笔','修者一代代凋零，魔枢典册却仍载其名，意义何在？','为留存来处，使后来者知今身所承','为论功行赏，记其境界高低','仅为管理之便，无甚深意','A','典册记的不是名次，是来处。知其承，方知其往。','2026-11-02 09:49:29'),(17,'掠夺之力有度否','噬魂大王','噬魂一系胜则夺人煞气，那么这种掠夺是否有上限？','无上限，胜者当得其全部','有上限，只取其该失之数，不敢尽取','掠夺与胜负无关，只看境界差','B','掠夺之力亦有分寸。噬魂一系胜时多得一份，而非尽夺。道有边际，方能长存。','2026-11-02 09:49:29'),(18,'无上何解','魔祖','十境之末为「无上」。既名无上，是否意味修行到此为止？','否，「无上」只是当前十重之顶，非道之尽头','是，到此已极，无可再进','无上即虚无，本质是放弃修行','A','「无上」是这十重体系之顶，不是道的顶。名可尽，而道不可尽。','2026-11-02 09:49:29'),(19,'静修与争锋','幽冥夫人','一方闭关千年不出，一方日日与人争锋，孰能更快进境？','闭关者，心不散则进境速','争锋者，切磋纳煞最快','二者各有其途，唯不宜偏废','C','闭关纳煞如储蓄，争锋切磋如练刀。蓄而不练则钝，练而不蓄则竭。','2026-11-02 09:49:29'),(20,'道号与真我','无名者','修者以道号入籍受拜，那么道号是否影响其修行命途？','影响，名入魔碑即是咒','不影响，名只是名，来去无痕','只在他人唤你时才短暂有意义','A','道号入碑，朝夕被唤，久而久之便成了自家所认的「我是谁」。名不是咒，却比咒更长久。','2026-11-02 09:49:29');
/*!40000 ALTER TABLE `demon_debate` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `demon_den`
--

DROP TABLE IF EXISTS `demon_den`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `demon_den` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '修者 id',
  `sha_level` int NOT NULL DEFAULT '0' COMMENT '聚煞阵等级（0=未开辟，上限10）',
  `coin_level` int NOT NULL DEFAULT '0' COMMENT '魔晶矿等级',
  `jade_level` int NOT NULL DEFAULT '0' COMMENT '血玉髓脉等级',
  `jade_carry` int NOT NULL DEFAULT '0' COMMENT '血玉千分位进位（1 血玉 = 1000）',
  `last_collect` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上次收取时间（累积起点）',
  `collect_date` date DEFAULT NULL COMMENT '每日结算记账日期（跨日自动清零）',
  `collected_sec` int NOT NULL DEFAULT '0' COMMENT '当日已累计结算秒数（上限 12h = 43200）',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_den_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='魔窟·洞府挂机产出';
/*!40101 SET character_set_client = @saved_cs_client */;

