DROP TABLE IF EXISTS `demon_trial`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `demon_trial` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '历练名',
  `region` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '地域',
  `realm_req` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '所需境界',
  `difficulty` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '凶险：低/中/高/绝',
  `summary` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '简介',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '配图相对路径',
  `boss` varchar(40) DEFAULT '' COMMENT '瀹堝叧濡栭瓟',
  `cost_exp` int NOT NULL DEFAULT '0' COMMENT '鍏ュ満娑堣?鐓炴皵',
  `daily_limit` int NOT NULL DEFAULT '3' COMMENT '姣忔棩鍙?叆娆℃暟',
  `reward_min` int NOT NULL DEFAULT '20' COMMENT '浜у嚭鐓炴皵涓嬮檺',
  `reward_max` int NOT NULL DEFAULT '60' COMMENT '浜у嚭鐓炴皵涓婇檺',
  `risk_rate` int NOT NULL DEFAULT '20' COMMENT '鍑堕櫓姒傜巼(鐧惧垎姣?',
  `treasure_rate` int NOT NULL DEFAULT '15' COMMENT '鏈虹紭姒傜巼(鐧惧垎姣?',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='域外秘境';
/*!40101 SET character_set_client = @saved_cs_client */;

