INSERT INTO `demon_trial` VALUES (1,'万骨荒原试炼','万骨荒原','魔卒','高','于白骨遍野之地淬炼杀性，活过三息者方入门。','2026-10-26 09:02:42','/images/trial/trial-1.jpg','白骨魔将',60,2,80,160,30,18),(2,'血海浮屠','血海','血煞','绝','渡血海而不溺，方证凶煞之身。','2026-10-26 09:02:42','/images/trial/trial-2.jpg','血海浮屠兽',150,1,200,400,45,25),(3,'幻月迷宫','幻月渊','魔卒','中','破幻月迷宫，明心见性，幻破则境开。','2026-10-26 09:02:42','/images/trial/trial-3.jpg','幻月魔狐',20,3,30,70,20,12),(4,'魔渊深处','无底魔渊','魔尊','绝','下探魔渊，窥见本源，然归来者寥寥。','2026-10-26 09:02:42','/images/trial/trial-4.jpg','渊底古魔',150,1,200,400,45,25),(5,'群魔论战','魔域演武场','魔尉','中','与同辈论战，砥砺道行，败者亦有所悟。','2026-10-26 09:02:42','/images/trial/trial-5.jpg','演武魁首',20,3,30,70,20,12),(6,'煞风峡谷','煞风峡','魔卒','中','穿煞风而过，炼体亦炼心，怯者退。','2026-10-26 09:02:42','/images/trial/trial-6.jpg','煞风鹰隼',20,3,30,70,20,12),(7,'冥河摆渡','冥河','魔尉','高','渡冥河寻彼岸，迷者沉，悟者渡。','2026-10-26 09:02:42','/images/trial/trial-7.jpg','冥河渡魂',60,2,80,160,30,18),(8,'万魔窟','万魔窟','魔将','绝','入万魔窟夺造化，九死一生，得者通玄。','2026-10-26 09:02:42','/images/trial/trial-8.jpg','万魔之主',150,1,200,400,45,25),(9,'残星台','残星台','魔尉','中','登残星台观星象，窥天机一角，悟者获益。','2026-10-26 09:02:42','/images/trial/trial-9.jpg','残星守者',20,3,30,70,20,12);
