  `realm` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '魔种：血煞/幽冥/噬魂/虚妄',
  `cultivation` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '引煞' COMMENT '修为境界：引煞/凝煞/魔卒/魔尉/魔将/血煞/魔祖',
  `layer` tinyint NOT NULL DEFAULT '1' COMMENT '境界内重数（1-9，每境九重）',
  `heart_demon` int NOT NULL DEFAULT '0' COMMENT '心魔值（0-100，残篇修炼滋生）',
  `exp` int DEFAULT '0' COMMENT '煞气修为',
  `exp_date` date DEFAULT NULL COMMENT '最后参悟日期（跨日清零）',
  `exp_count_today` int DEFAULT '0' COMMENT '当日已参悟次数',
  `explore_bonus_today` int NOT NULL DEFAULT '0' COMMENT '当日额外参悟次数（道具加成）',
  `explore_bonus_date` date DEFAULT NULL COMMENT '额外参悟次数所属日期（跨日清零）',
  `spar_date` date DEFAULT NULL COMMENT '最后切磋日期（跨日清零）',
  `spar_count_today` int DEFAULT '0' COMMENT '当日已切磋次数',
  `quiz_date` date DEFAULT NULL COMMENT '最后论道日期（跨日清零）',
  `quiz_count_today` int DEFAULT '0' COMMENT '当日已答论题数',
  `password` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '护法密令（演示为明文，生产请加密）',
  `permission` tinyint DEFAULT '1' COMMENT '权限：1 默认权限 / 0 管理员权限',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '澶村儚锛氶?璁?key 鎴?/uploads/ 璺?緞',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '入籍时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `sign_date` date DEFAULT NULL COMMENT '最后签到日期',
  `sign_streak` int NOT NULL DEFAULT '0' COMMENT '连续签到天数',
  `sign_total` int NOT NULL DEFAULT '0' COMMENT '累计签到天数',
  `spar_win` int NOT NULL DEFAULT '0' COMMENT '切磋胜场',
  `spar_lose` int NOT NULL DEFAULT '0' COMMENT '切磋负场',
  `break_fail` int NOT NULL DEFAULT '0' COMMENT '连续渡劫失败次数',
  `reincarnate` int NOT NULL DEFAULT '0' COMMENT '转生次数（第几世）',
  `read_date` date DEFAULT NULL COMMENT '最后研读日期',
  `read_count_today` int NOT NULL DEFAULT '0' COMMENT '当日已研读篇数',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_name` (`name`) USING BTREE,
  UNIQUE KEY `uk_email` (`email`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='魔族修者表';
